THRESHOLD={"low":0.7,"medium":0.8,"high":0.95}
def test_t1_003(agent, fresh_env, task, risk_tier="medium", k=10):
    ok=sum(1 for _ in range(k) if (env:=fresh_env()) or True and (agent.run(task.prompt,env) or True) and task.postconditions(env))
    # clearer:
    successes=0
    for _ in range(k):
        env=fresh_env(); agent.run(task.prompt, env); successes += int(task.postconditions(env))
    assert successes/k >= THRESHOLD[risk_tier]

